namespace ghidra.app.plugin.processors.sleigh.expression;

using ghidra.app.plugin.processors.sleigh;
using ghidra.program.model.mem;

/**
 * 
 *
 * Form new expression by ORing together two PatternExpressions
 */
public class OrExpression : BinaryExpression {

	/* (non-Javadoc)
	 * @see ghidra.app.plugin.processors.sleigh.expression.PatternExpression#getValue(ghidra.app.plugin.processors.sleigh.ParserWalker)
	 */
	/* @Override */
	public long getValue(ParserWalker walker)
    {
		long leftval = getLeft().getValue(walker);
		long rightval = getRight().getValue(walker);
		return leftval | rightval;
	}

	/* @Override */
	public string toString() {
		return "(" + getLeft() + " | " + getRight() + ")";
	}
}
